use aa_mapworld::{MapArchive,Inventory};
use serde_json::json;
use std::{collections::BTreeMap,path::{Path,PathBuf}};
fn paths(p:&Path,v:&mut Vec<PathBuf>){for e in std::fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){paths(&p,v)}else if p.extension().is_some_and(|e|e.eq_ignore_ascii_case("rmp")){v.push(p)}}}
fn main(){let root=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../reconstruction/assets/original/Data/Maps");let mut maps=Vec::new();paths(&root,&mut maps);maps.sort();let mut masks=BTreeMap::new();let mut examples=BTreeMap::new();let mut versions=BTreeMap::new();for p in maps{let map=MapArchive::from_bytes(std::fs::read(&p).unwrap()).unwrap();let inv=Inventory::decode(&map,128<<20).unwrap();for r in inv.placements {if let Some(a)=r.actor {let d=u32::from_le_bytes(r.opaque_tail[..4].try_into().unwrap());let s=u32::from_le_bytes(r.opaque_tail[4..8].try_into().unwrap());let key=format!("{d:08x}/{s:08x}");*masks.entry(key.clone()).or_insert(0usize)+=1;examples.entry(key).or_insert(json!({"map":p,"ordinal":r.record_ordinal,"id":String::from_utf16_lossy(&r.thing_id_utf16),"record_offset":r.source_span.offset,"record_length":r.source_span.length,"tail_offset":r.opaque_tail_span.offset,"tail_length":r.opaque_tail.len()}));*versions.entry(a.version).or_insert(0usize)+=1;}}}println!("{}",serde_json::to_string_pretty(&json!({"default_saved_masks":masks,"examples":examples,"versions":versions})).unwrap());}
